from collections import deque

def resolve(path, cwd, links):
    def parts(p):
        return [x for x in p.split('/') if x not in ('', '.')]

    def parent(cur):
        if cur == '/':
            return '/'
        idx = cur.rfind('/')
        if idx <= 0:
            return '/'
        return cur[:idx]

    def join(cur, name):
        if cur == '/':
            return '/' + name
        return cur + '/' + name

    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    queue = deque(parts(path))
    link_count = 0

    while queue:
        c = queue.popleft()
        if c == '..':
            current = parent(current)
        else:
            candidate = join(current, c)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                target_parts = parts(target)
                if target.startswith('/'):
                    # absolute target, resolution starts fresh from root
                    # we need to reset current to root and process target_parts first,
                    # then continue with rest of queue
                    new_queue = deque(target_parts)
                    new_queue.extend(queue)
                    queue = new_queue
                    current = '/'
                else:
                    # relative to directory containing the link, which is `current`
                    new_queue = deque(target_parts)
                    new_queue.extend(queue)
                    queue = new_queue
                    # current stays the same (the directory containing the link)
            else:
                current = candidate

    return current

